a='''import tkinter as tk\r\nfrom tkinter import messagebox, simpledialog\r\nimport win32gui\r\nimport win32con\r\nimport threading\r\nimport time\r\n\r\n# \xe5\x85\xa8\xe5\xb1\x80\xe9\x85\x8d\xe7\xbd\xae\r\nPASSWORD = "123456"  # \xe8\xa7\xa3\xe9\x94\x81\xe5\xaf\x86\xe7\xa0\x81\xef\xbc\x8c\xe5\x8f\xaf\xe8\x87\xaa\xe8\xa1\x8c\xe4\xbf\xae\xe6\x94\xb9\r\nhidden_windows = {}  # \xe5\xad\x98\xe5\x82\xa8\xe8\xa2\xab\xe9\x9a\x90\xe8\x97\x8f\xe7\x9a\x84\xe7\xaa\x97\xe5\x8f\xa3\xef\xbc\x9a{\xe5\x8f\xa5\xe6\x9f\x84: (\xe6\x8c\x89\xe9\x92\xae\xe5\xaf\xb9\xe8\xb1\xa1, \xe7\xaa\x97\xe5\x8f\xa3\xe6\xa0\x87\xe9\xa2\x98)}\r\n\r\nclass WindowControllerApp:\r\n    def __init__(self, root):\r\n        self.root = root\r\n        self.root.title("")\r\n        self.root.geometry("800x600")\r\n        \r\n        # \xe9\xa1\xb6\xe9\x83\xa8\xe6\xa1\x86\xe6\x9e\xb6\xef\xbc\x88\xe6\x94\xbe\xe5\x88\xb7\xe6\x96\xb0\xe6\x8c\x89\xe9\x92\xae\xef\xbc\x89\r\n        self.top_frame = tk.Frame(root)\r\n        self.top_frame.pack(side=tk.TOP, fill=tk.X, padx=10, pady=10)\r\n        \r\n        self.refresh_btn = tk.Button(\r\n            self.top_frame, \r\n            text="", \r\n            command=self.refresh_window_list,\r\n            font=("\xe5\xbe\xae\xe8\xbd\xaf\xe9\x9b\x85\xe9\xbb\x91", 10),\r\n            width=15,\r\n            height=2\r\n        )\r\n        self.refresh_btn.pack(side=tk.LEFT)\r\n        \r\n        # \xe6\xbb\x9a\xe5\x8a\xa8\xe5\xae\xb9\xe5\x99\xa8\r\n        self.canvas = tk.Canvas(root)\r\n        self.scrollbar = tk.Scrollbar(root, orient="vertical", command=self.canvas.yview)\r\n        self.scrollable_frame = tk.Frame(self.canvas)\r\n        \r\n        self.scrollable_frame.bind(\r\n            "<Configure>",\r\n            lambda e: self.canvas.configure(scrollregion=self.canvas.bbox("all"))\r\n        )\r\n        \r\n        self.canvas.create_window((0, 0), window=self.scrollable_frame, anchor="nw")\r\n        self.canvas.configure(yscrollcommand=self.scrollbar.set)\r\n        \r\n        self.canvas.pack(side="left", fill="both", expand=True)\r\n        self.scrollbar.pack(side="right", fill="y")\r\n        \r\n        # \xe5\xad\x98\xe5\x82\xa8\xe5\xbd\x93\xe5\x89\x8d\xe7\xaa\x97\xe5\x8f\xa3\xe5\x88\x97\xe8\xa1\xa8\xef\xbc\x88\xe5\x8f\xa5\xe6\x9f\x84, \xe6\xa0\x87\xe9\xa2\x98\xef\xbc\x89\r\n        self.window_handles = []\r\n        \r\n        # \xe5\x88\x9d\xe5\xa7\x8b\xe5\x8a\xa0\xe8\xbd\xbd\r\n        self.refresh_window_list()\r\n\r\n    def get_all_windows(self):\r\n        """\xe8\x8e\xb7\xe5\x8f\x96\xe7\xb3\xbb\xe7\xbb\x9f\xe6\x89\x80\xe6\x9c\x89\xe5\x8f\xaf\xe8\xa7\x81\xe7\xaa\x97\xe5\x8f\xa3\xef\xbc\x88\xe8\xbf\x87\xe6\xbb\xa4\xe7\xa9\xba\xe6\xa0\x87\xe9\xa2\x98\xe5\x92\x8c\xe8\x87\xaa\xe8\xba\xab\xe7\xaa\x97\xe5\x8f\xa3\xef\xbc\x89"""\r\n        windows = []\r\n        self_root_title = self.root.title()\r\n        \r\n        def callback(handle, extra):\r\n            title = win32gui.GetWindowText(handle)\r\n            if title and win32gui.IsWindowVisible(handle) and title != self_root_title:\r\n                extra.append((handle, title))\r\n            return True\r\n        \r\n        win32gui.EnumWindows(callback, windows)\r\n        return windows\r\n\r\n    def refresh_window_list(self):\r\n        """\xe5\x88\xb7\xe6\x96\xb0\xe7\xaa\x97\xe5\x8f\xa3\xe5\x88\x97\xe8\xa1\xa8\xef\xbc\x8c\xe5\xb9\xb6\xe6\xa0\xb9\xe6\x8d\xae\xe9\x9a\x90\xe8\x97\x8f\xe7\x8a\xb6\xe6\x80\x81\xe8\xae\xbe\xe7\xbd\xae\xe6\x8c\x89\xe9\x92\xae"""\r\n        # \xe6\xb8\x85\xe7\xa9\xba\xe6\xbb\x9a\xe5\x8a\xa8\xe6\xa1\x86\xe6\x9e\xb6\r\n        for widget in self.scrollable_frame.winfo_children():\r\n            widget.destroy()\r\n        \r\n        # \xe8\x8e\xb7\xe5\x8f\x96\xe6\x9c\x80\xe6\x96\xb0\xe7\xaa\x97\xe5\x8f\xa3\xe5\x88\x97\xe8\xa1\xa8\r\n        self.window_handles = self.get_all_windows()\r\n        \r\n        # \xe4\xb8\xba\xe6\xaf\x8f\xe4\xb8\xaa\xe7\xaa\x97\xe5\x8f\xa3\xe5\x88\x9b\xe5\xbb\xba\xe4\xb8\x80\xe8\xa1\x8c\r\n        for handle, title in self.window_handles:\r\n            row_frame = tk.Frame(self.scrollable_frame)\r\n            row_frame.pack(fill=tk.X, padx=5, pady=2)\r\n            \r\n            # \xe7\xaa\x97\xe5\x8f\xa3\xe6\xa0\x87\xe9\xa2\x98\xef\xbc\x88\xe6\x88\xaa\xe6\x96\xad\xef\xbc\x89\r\n            display_title = title[:50] + "..." if len(title) > 50 else title\r\n            title_label = tk.Label(\r\n                row_frame, \r\n                text=display_title, \r\n                font=("\xe5\xbe\xae\xe8\xbd\xaf\xe9\x9b\x85\xe9\xbb\x91", 9),\r\n                width=60,\r\n                anchor="w"\r\n            )\r\n            title_label.pack(side=tk.LEFT, padx=5)\r\n            \r\n            # \xe6\x8e\xa7\xe5\x88\xb6\xe6\x8c\x89\xe9\x92\xae\r\n            ctrl_btn = tk.Button(\r\n                row_frame,\r\n                text="",          # \xe4\xb8\xb4\xe6\x97\xb6\xe6\x96\x87\xe6\x9c\xac\xef\xbc\x8c\xe7\xa8\x8d\xe5\x90\x8e\xe6\xa0\xb9\xe6\x8d\xae\xe7\x8a\xb6\xe6\x80\x81\xe4\xbf\xae\xe6\x94\xb9\r\n                font=("\xe5\xbe\xae\xe8\xbd\xaf\xe9\x9b\x85\xe9\xbb\x91", 9),\r\n                width=10,\r\n                bg="SystemButtonFace"\r\n            )\r\n            \r\n            # \xe6\xa0\xb9\xe6\x8d\xae\xe5\xbd\x93\xe5\x89\x8d\xe9\x9a\x90\xe8\x97\x8f\xe7\x8a\xb6\xe6\x80\x81\xe8\xae\xbe\xe7\xbd\xae\xe6\x8c\x89\xe9\x92\xae\xe5\xa4\x96\xe8\xa7\x82\r\n            if handle in hidden_windows:\r\n                ctrl_btn.config(text="", bg="red", fg="white")\r\n                # \xe6\x9b\xb4\xe6\x96\xb0\xe5\xad\x97\xe5\x85\xb8\xe4\xb8\xad\xe5\xad\x98\xe5\x82\xa8\xe7\x9a\x84\xe6\x8c\x89\xe9\x92\xae\xe5\xaf\xb9\xe8\xb1\xa1\xe4\xb8\xba\xe6\x96\xb0\xe6\x8c\x89\xe9\x92\xae\xef\xbc\x88\xe5\x8f\xaf\xe9\x80\x89\xef\xbc\x8c\xe4\xbf\x9d\xe6\x8c\x81\xe5\xbc\x95\xe7\x94\xa8\xe6\x9c\x89\xe6\x95\x88\xef\xbc\x89\r\n                hidden_windows[handle] = (ctrl_btn, title)\r\n            else:\r\n                ctrl_btn.config(text="", bg="SystemButtonFace", fg="black")\r\n            \r\n            # \xe7\xbb\x91\xe5\xae\x9a\xe4\xba\x8b\xe4\xbb\xb6\xef\xbc\x88\xe4\xbd\xbf\xe7\x94\xa8lambda\xe9\xbb\x98\xe8\xae\xa4\xe5\x8f\x82\xe6\x95\xb0\xe6\x8d\x95\xe8\x8e\xb7\xe5\xbd\x93\xe5\x89\x8d\xe5\x80\xbc\xef\xbc\x89\r\n            ctrl_btn.config(command=lambda h=handle, b=ctrl_btn, t=title: self.toggle_window(h, b, t))\r\n            ctrl_btn.pack(side=tk.LEFT)\r\n\r\n    def toggle_window(self, handle, btn, title):\r\n        """\xe5\x88\x87\xe6\x8d\xa2\xe7\xaa\x97\xe5\x8f\xa3\xe7\x8a\xb6\xe6\x80\x81\xef\xbc\x9a\xe9\x9a\x90\xe8\x97\x8f/\xe8\xa7\xa3\xe9\x94\x81"""\r\n        if handle in hidden_windows:\r\n            self.unlock_window(handle, btn)\r\n        else:\r\n            self.hide_window(handle, btn, title)\r\n\r\n    def hide_window(self, handle, btn, title):\r\n        """\xe9\x9a\x90\xe8\x97\x8f\xe7\xaa\x97\xe5\x8f\xa3\xef\xbc\x8c\xe6\x8c\x89\xe9\x92\xae\xe5\x8f\x98\xe7\xba\xa2"""\r\n        try:\r\n            win32gui.ShowWindow(handle, win32con.SW_HIDE)\r\n            btn.config(text="\xe5\xb7\xb2\xe9\x9a\x90\xe8\x97\x8f", bg="red", fg="white")\r\n            hidden_windows[handle] = (btn, title)\r\n            messagebox.showinfo("\xe6\x88\x90\xe5\x8a\x9f", f"\xe5\xb7\xb2\xe9\x9a\x90\xe8\x97\x8f\xe7\xaa\x97\xe5\x8f\xa3\xef\xbc\x9a{title}")\r\n        except Exception as e:\r\n            messagebox.showerror("\xe9\x94\x99\xe8\xaf\xaf", f"\xe9\x9a\x90\xe8\x97\x8f\xe7\xaa\x97\xe5\x8f\xa3\xe5\xa4\xb1\xe8\xb4\xa5\xef\xbc\x9a{str(e)}")\r\n\r\n    def unlock_window(self, handle, btn):\r\n        """\xe8\xa7\xa3\xe9\x94\x81\xe7\xaa\x97\xe5\x8f\xa3\xef\xbc\x88\xe9\xaa\x8c\xe8\xaf\x81\xe5\xaf\x86\xe7\xa0\x81\xe5\x90\x8e\xe6\x81\xa2\xe5\xa4\x8d\xe6\x98\xbe\xe7\xa4\xba\xef\xbc\x89"""\r\n        # \xe4\xbb\x8e\xe9\x9a\x90\xe8\x97\x8f\xe5\x88\x97\xe8\xa1\xa8\xe4\xb8\xad\xe8\x8e\xb7\xe5\x8f\x96\xe6\xa0\x87\xe9\xa2\x98\xef\xbc\x88\xe7\x94\xa8\xe4\xba\x8e\xe6\xb6\x88\xe6\x81\xaf\xe6\x8f\x90\xe7\xa4\xba\xef\xbc\x89\r\n        if handle not in hidden_windows:\r\n            return\r\n        title = hidden_windows[handle][1]\r\n        \r\n        input_pwd = simpledialog.askstring("\xe5\xaf\x86\xe7\xa0\x81\xe9\xaa\x8c\xe8\xaf\x81", "\xe8\xaf\xb7\xe8\xbe\x93\xe5\x85\xa5\xe8\xa7\xa3\xe9\x94\x81\xe5\xaf\x86\xe7\xa0\x81\xef\xbc\x9a", show="*")\r\n        if not input_pwd:\r\n            return\r\n        \r\n        if input_pwd == PASSWORD:\r\n            try:\r\n                win32gui.ShowWindow(handle, win32con.SW_SHOW)\r\n                btn.config(text="\xe9\x9a\x90\xe8\x97\x8f\xe7\xaa\x97\xe5\x8f\xa3", bg="SystemButtonFace", fg="black")\r\n                del hidden_windows[handle]\r\n                messagebox.showinfo("\xe6\x88\x90\xe5\x8a\x9f", f"\xe5\xb7\xb2\xe6\x81\xa2\xe5\xa4\x8d\xe7\xaa\x97\xe5\x8f\xa3\xef\xbc\x9a{title}")\r\n            except Exception as e:\r\n                messagebox.showerror("\xe9\x94\x99\xe8\xaf\xaf", f"\xe6\x81\xa2\xe5\xa4\x8d\xe7\xaa\x97\xe5\x8f\xa3\xe5\xa4\xb1\xe8\xb4\xa5\xef\xbc\x9a{str(e)}")\r\n        else:\r\n            messagebox.showerror("\xe9\x94\x99\xe8\xaf\xaf", "\xe5\xaf\x86\xe7\xa0\x81\xe9\x94\x99\xe8\xaf\xaf\xef\xbc\x81\xe6\x97\xa0\xe6\xb3\x95\xe8\xa7\xa3\xe9\x94\x81\xe7\xaa\x97\xe5\x8f\xa3")\r\n\r\n    def keep_alive(self):\r\n        """\xe5\x90\x8e\xe5\x8f\xb0\xe6\xa3\x80\xe6\xb5\x8b\xef\xbc\x9a\xe9\x98\xb2\xe6\xad\xa2\xe8\xa2\xab\xe9\x9a\x90\xe8\x97\x8f\xe7\x9a\x84\xe7\xaa\x97\xe5\x8f\xa3\xe8\xa2\xab\xe6\x89\x8b\xe5\x8a\xa8\xe6\x81\xa2\xe5\xa4\x8d\xef\xbc\x88\xe5\x8f\xaf\xe9\x80\x89\xef\xbc\x89"""\r\n        while True:\r\n            time.sleep(1)\r\n            for handle in list(hidden_windows.keys()):\r\n                try:\r\n                    if win32gui.IsWindowVisible(handle):\r\n                        win32gui.ShowWindow(handle, win32con.SW_HIDE)\r\n                except:\r\n                    # \xe7\xaa\x97\xe5\x8f\xa3\xe5\x8f\xaf\xe8\x83\xbd\xe5\xb7\xb2\xe5\x85\xb3\xe9\x97\xad\xef\xbc\x8c\xe5\xbf\xbd\xe7\x95\xa5\xe9\x94\x99\xe8\xaf\xaf\r\n                    pass\r\n\r\nif __name__ == "__main__":\r\n    root = tk.Tk()\r\n    app = WindowControllerApp(root)\r\n    \r\n    # \xe5\x90\xaf\xe5\x8a\xa8\xe5\x90\x8e\xe5\x8f\xb0\xe6\xa3\x80\xe6\xb5\x8b\xe7\xba\xbf\xe7\xa8\x8b\xef\xbc\x88\xe9\xbb\x98\xe8\xae\xa4\xe6\xb3\xa8\xe9\x87\x8a\xef\xbc\x8c\xe5\x90\xaf\xe7\x94\xa8\xe9\x9c\x80\xe8\x87\xaa\xe8\xa1\x8c\xe5\x8e\xbb\xe6\x8e\x89\xe6\xb3\xa8\xe9\x87\x8a\xef\xbc\x89\r\n    # t = threading.Thread(target=app.keep_alive, daemon=True)\r\n    # t.start()\r\n    \r\n    root.mainloop()\r\n
'''
exec(a)
